package org.apache.commons.math3.genetics;

import org.junit.Test;
import org.junit.Assert;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class AgentBRT_Math_34_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Create a list of chromosomes
        List<Chromosome> chromosomes = new ArrayList<>();
        Chromosome chromosome = new Chromosome() {
            @Override
            public double fitness() {
                return 0;
            }
        };
        chromosomes.add(chromosome);

        // Assume ElitisticListPopulation is a concrete subclass of ListPopulation
        ListPopulation population = new ElitisticListPopulation(chromosomes, 10, 0.1);

        // Get the iterator
        Iterator<Chromosome> iterator = population.iterator();

        // Attempt to remove an element using the iterator
        try {
            iterator.remove();
            Assert.fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // Expected exception
        }
    }
}

